  VALUES 
    (41::BIGINT, 'Buen profesor, curso relativamente difícil, aplica tareas todas las semanas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-03T00:00:00+00:00'::TIMESTAMPTZ, '474ec302d96d5571d6304599803c4988b9e13a0340d87890e93bda20e7c89cf8'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Profe por favor haga las practicas bien, no somos adivinos para entender un chorro de números regados en un excel'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '71f57c5d8e8e4dca078d7c520a98487ea8d9930ca11c2aa7d76b1f78c5cf3473'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Muy amable, siempre dispuesto a ayudar. Si estudia y practica mucho pasar es sencillo. Casi no contesta correos, pero por msj si'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'aa04b47bf7cc4e9b949bbb5b5af1bf3cee1c8809376aaaf1d80e0de48c94a14c'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'La asistente hace todo. Sus prácticas son demasiado desordenadas y casi no se entiende. Las clases son súper largas y uno se pierde fácil. Al menos en mi caso los exámenes los evalúo en un 75% lo cuál hizo muy difícil pasar el curso'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-08-09T00:00:00+00:00'::TIMESTAMPTZ, '72bb79171d289562909768f68b2d3cfc9eebb49e024bd3a2f7c096e323a7492d'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Prácticas desordenadas y algunos aspectos de enseñanza que necesitan actualización, realizó algunos quices y el primer examen en papel, califica mas o menos duro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '50f16f28a58b25b864d09a3a28c9fcf1d64f43042766dc1c7ca05c5108d26d8b'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Al principio explicaba bien y era buen profesor , pero hizo el primer examen y unos quices en papel, luego se volvió todo muy autodidacta y pedía explicar casos cuando vimos muy pocos ejercicios de la materia. Los Excel que brindaba era muy desordenado y las soluciones muchas veces estaban mal.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9847e7b067db934b906ec3a6fe736197835ea8433d74b087cac711a05c92825b'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Se ve que conoce mucho del tema tanto a nivel nacional como internacional. Sin embargo, trata de implementar un modelo pedagógico donde uno como estudiante debe ser autodidacta y a veces es complicado. El primer examen y un par de quizes los realizó en papel.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '74660d015ad77bbce20734ade9c10f31381324b0297301c8b2e13c56ca02bd88'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Al trabajar con Contabilidad no organiza nada y el material es extremadamente desordenado Todo lo hace y califica el asistente Hace preguntas que si no la responde con las palabras que quiere, están mal. Es desactualizado, hace exámenes de contabilidad en papel'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd9a21c18f20b0e409e9d5987f8064145834c1908a55308c0dccffa95fba23df7'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Conoce muy de la realidad nacional e internacional. Excelente exposición y aclara dudas. Respetuoso de todas las y los estudiantes en su clase'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-05-14T00:00:00+00:00'::TIMESTAMPTZ, '61d8f3bb9c263beb09c22b6b5be7194bdf3b627cc4f8cf9ab521b04206f57999'::TEXT, ARRAY[2366, 2361]::BIGINT[]),
    (41::BIGINT, 'Se preocupa mucho por los estudiantes. Explica muy claro y en realidad, los quices y exámenes son sencillos si va al día con la materia. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '442449f47c3d24e75d7bafd5a6d1f15b13988e7c97954f1a719fa9a1c3c563dc'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'De los mejores profes de la escuela. Se preocupa demasiado por los estudiantes y por que realmente aprendan. Explica la materia las veces que sean necesarias sin problema alguno. Los exámenes y quizes siempre los califica en 8 días y es muy claro con todo. No se van a arrepentir.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2bfb54debfef991097204bd50b2375d11e31cf96c94802bb5f1eed0f5fb1ecf1'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'Es un excelente profesor está dispuesto ayudar al estudiante eso si hay que mostrar interés y hacer todas las prácticas, los exámenes son largos, pero si se realizan las prácticas se resuelven con facilidad, los quizzes se realizan una semana antes de cada examen ayudan mucho para pulir detalles'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6eb53af9f943d4bcffcc5de758cd8249bcc214e6d88f0f1db4f4717602d52e6f'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'De los mejores profes, explica todo de forma clara y no asume que sabemos las cosas, mas bien consulta si alguien no ha visto algún tema y lo retoma. Si hace las practicas el examen se vuelve facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b1c78e92119eca25f6be7200318fef4e09047f49274ba07d01c81374c47a356b'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'La clase es larga, pero se entiende, es un buen profe, y los exámenes son las tareas, entonces al menos virtual se puede revisar la tarea en el examen y puede ver bien como hacer todo entonces eso lo hace más fácil'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-01T00:00:00+00:00'::TIMESTAMPTZ, '6025c23337923a998e86b9e0797e3480263289291f90558330f2412280182198'::TEXT, ARRAY[2361, 2366]::BIGINT[]),
    (41::BIGINT, 'El profesor explica muy bien, le gusta la participación de hecho pasa asistencia preguntando por lista, se debe llevar siempre la materia al día sino se va a quedar perdido, siempre está para el estudiante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '1a47093236dd726952b8bd22bfc4b92d1186187e62b7925182ed47c682c485d4'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '172a34f1d76db60fd9d4960b0f5bf66d9bb9b9e1a1d1040e614b8e60fa180577'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Si estás buscando aprender este profesor te conviene, sin embargo hay que practicar mucho para entender bien la materia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7e5a23cbcc8e12a6802b2716417c9ca106c78603cdb56cd8e10ee70c730a5aeb'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Excelente profesor, explica muy bien y tiene un amplio conocimiento del tema.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'acd7efc4544d10c959c2648833cdac10830f413748a2e546cc07fbe4611be4e1'::TEXT, ARRAY[1515]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'b6621d84506f31d91c0d62b4153ca3e545fde24b52115aa4d9e8cdf0c5af4980'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Es muy bueno explicando, lo malo es que el no califica nada es la asistente entonces cuesta mucho que corrija algún error, las soluciones de las prácticas nunca las hace el siempre son de algún compañero por lo cual aveces tienen errores y nunca los corrige, tareas larguísimas y no valen nada'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '76ea439ee336bbb83e7d8fa050f146629c8725c1f0ed39ca0bf59eb3913bf529'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '387588fe8ac7df4fa795f2066fe3bee67fe61045556c7a2e1f969ac690f09fa9'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-01-21T00:00:00+00:00'::TIMESTAMPTZ, '695a20cb2330295c6f7e00e8becc451c00340dfdb35a0fef7b7e9f0bd038a748'::TEXT, ARRAY[2366, 2361]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, '4764f1a249b5d3757f09f6c802e094ac83970cd358cc919f7d40e9c9c2bb9569'::TEXT, ARRAY[2366, 2361]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '89246079639d8158008f76f5e58787dd214e80c7387e60005e6a8f91ef18c769'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ab11850e6ac188e920a61e910f0974cf4cbfa8627b15c76b45d8a5323a706721'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'Muy buen profesor, explica muy bien la materia y si esta disponible en su oficina siempre atiende y se preocupa por los estudiantes. En el trabajo final no ayuda mucho pero no califica duro si se cumple con lo solicitado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fd8daca82644d5a76f4c2de744ee7b6c1255ba42f77645507a58fb6aa46c432f'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'El profesor sabe muy bien de la materia y la explica perfectamente bien. Los temas del curso son muy fáciles y los exámenes también. Quizes fáciles, tareas fáciles, si usted entiende conta. El proyecto es fácil solo que para atender dudas normalmente no tiene tiempo. 100% recomendado y cae bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'abc4e72ec0074bc6fead9addda7585f393ebe47474d6ba803daf81a33e1576c4'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'No lo recomiendo, es un profesor ocupado, a veces tiene tiempo para atenderlo en consulta, el proyecto es algo difícil y no hay retroalimentación del profesor sino de la asistente.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f811d516b3889c4bfb9b84c19a6722a78f6ca0ebeb851b3602642e4cc46164b6'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Es el tipico profesor que tiene tanto que hacer que espera mucho. Sin embargo, no brinda tiempo de consulta adecuadamente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'bd19427a9f182211c78d3f0b5d9b4a1f849a79dad035804f91dbba5eff0d5a51'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'No deja tareas y tampoco hace quices. Cuesta entender por la velocidad en la que da las clases. Siento que su técnica pedagógica es poco intuitiva y el proyecto lo califica demasiado duro.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, '1ebca2e60f1890067d00c9e217cecbbdb6e5dc2bf811a972dbaedae7738b6fe9'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Muy buen profe, se le entiende la materia súper bien y si ocupas ayuda o que te vuelva a explicar él lo hace, es el mejor!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '16d5661dd984198baadb9149ba576df015ee7b7d8868d806a1eafff87f330d42'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'Un profesor excelente, dedicado a sus estudiantes y al curso, no siempre tiene tiempo, pero si se le busca siempre esta dispuesto a explicar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd6814ba56857b4503b988a815bdd2193410d97f42ee74c50c0faa3aee8201173'::TEXT, ARRAY[2366]::BIGINT[]),
    (41::BIGINT, 'Explica bien, pero a veces da la materia muy rápido'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '34ecdad1db1fb6b8fee96d0819175e2497dce1828a10d993c6b049569aa8a22a'::TEXT, ARRAY[2361]::BIGINT[]),
    (41::BIGINT, 'Excelente profe, explica super bien, tiene demasiada paciencia y se preocupa porque aprendamos. Ha sido el mejor hasta el momento lo recomiendo!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'a907cdbe0857a8afcc84928f83960d84e7fa9d9fcfd582d5ec3613d666a61a50'::TEXT, ARRAY[2361]::BIGINT[]),
